import { motion } from 'framer-motion';
import { Play } from 'lucide-react';
import { films } from '@/data/films';
import { FILMS } from '@/constants/testIds/portfolio';
import { FadeUp } from './Reveal';

const FilmCard = ({ film, onOpen, large }) => (
  <motion.button
    onClick={() => onOpen(film)}
    data-testid={FILMS.card}
    initial={{ opacity: 0, y: 40 }}
    whileInView={{ opacity: 1, y: 0 }}
    viewport={{ once: true, margin: '-60px' }}
    transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
    className={`group relative block w-full overflow-hidden text-left border border-white/10 ${
      large ? 'aspect-[16/10]' : 'aspect-[4/3]'
    }`}
  >
    <img
      src={film.thumb}
      alt={film.title}
      className="absolute inset-0 w-full h-full object-cover grayscale-[35%] group-hover:grayscale-0 group-hover:scale-105 transition-all duration-700"
    />
    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/30 to-transparent" />

    <span className="absolute top-4 left-4 text-[10px] tracking-[0.2em] uppercase bg-black/60 backdrop-blur px-3 py-1.5 border border-white/10">
      {film.kind}
    </span>
    <span className="absolute top-4 right-4 text-[10px] tracking-[0.2em] uppercase text-white/70">
      {film.duration}
    </span>

    <span className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
      <span className="flex items-center justify-center w-16 h-16 rounded-full bg-[#E11D48] text-white scale-90 group-hover:scale-100 transition-transform duration-300">
        <Play className="w-6 h-6 fill-current ml-1" />
      </span>
    </span>

    <div className="absolute bottom-0 left-0 right-0 p-5 md:p-7">
      <div className="flex items-center gap-3 text-[11px] tracking-[0.2em] uppercase text-white/60 mb-2">
        <span className="text-[#E11D48]">{film.genre}</span>
        <span>·</span>
        <span>{film.year}</span>
        <span>·</span>
        <span>{film.views} views</span>
      </div>
      <h3 className={`font-display font-semibold uppercase leading-none ${large ? 'text-4xl md:text-6xl' : 'text-2xl md:text-3xl'}`}>
        {film.title}
      </h3>
    </div>
  </motion.button>
);

export const Films = ({ onOpen }) => {
  const [feature, ...rest] = films;
  return (
    <section id="work" data-testid={FILMS.section} className="px-6 md:px-12 py-28 md:py-40">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-14">
        <FadeUp>
          <span className="text-[11px] tracking-[0.3em] uppercase text-[#E11D48]">[ Selected Work ]</span>
          <h2 className="font-display font-semibold text-5xl md:text-8xl uppercase leading-[0.9] mt-5">
            The Films
          </h2>
        </FadeUp>
        <FadeUp delay={0.1}>
          <p className="text-white/50 text-sm max-w-xs md:text-right">
            Click any frame to watch it right here — pulled straight from the channel.
          </p>
        </FadeUp>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 md:gap-5">
        <div className="lg:col-span-2">
          <FilmCard film={feature} onOpen={onOpen} large />
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-4 md:gap-5">
          {rest.slice(0, 2).map((f) => (
            <FilmCard key={f.id} film={f} onOpen={onOpen} />
          ))}
        </div>
        {rest.slice(2).map((f) => (
          <FilmCard key={f.id} film={f} onOpen={onOpen} />
        ))}
      </div>
    </section>
  );
};
